/**
 * @file    CanTp_Lcfg.c
 * @brief   Configuration tables of the example CanTp.
 *
 * In a real project this file is GENERATED by the configuration tool.
 * Timing values are EXAMPLE values. Real values come from the OEM
 * specification / ISO 15765-2 (not among the provided PDFs). They must keep
 * the ISO 15765-2 performance rules quoted by the SWS:
 *   (N_Br + N_Ar) < 0.9 * N_Bs   (SWS 7.3.1, note after [SWS_CanTp_00222])
 *   (N_Cs + N_As) < 0.9 * N_Cr   (SWS 7.3.2, note after [SWS_CanTp_00184])
 */
#include "CanTp_Internal.h"

/* Example timing in ms [Practice] */
#define CANTP_EX_NAR_MS     70u
#define CANTP_EX_NAS_MS     70u
#define CANTP_EX_NBR_MS     20u    /* 20 + 70 = 90  < 0.9 * 150 */
#define CANTP_EX_NBS_MS     150u
#define CANTP_EX_NCS_MS     20u    /* 20 + 70 = 90  < 0.9 * 150 */
#define CANTP_EX_NCR_MS     150u

/* Example flow control parameters sent by this ECU as receiver */
#define CANTP_EX_BS         ((uint8)2u)      /* FC after every 2 CFs          */
#define CANTP_EX_STMIN      ((uint8)0x05u)   /* 5 ms between two CFs          */
#define CANTP_EX_WFTMAX     ((uint16)3u)     /* at most 3 consecutive FC(WAIT) */

/* ---- CanTpRxNSdu: index = CanTpRxNSduId --------------------------------- */
const CanTp_RxNSduCfgType CanTp_RxNSduCfg[CANTP_CFG_NUM_RX_NSDU] =
{
    {   /* CanTpConf_CanTpRxNSdu_DiagPhysRx: physical requests on 0x7E0 */
        CanTpConf_CanTpRxNPdu_Req7E0,
        CANTP_CFG_PDUR_DIAG_PHYS_RX,
        CANTP_CFG_LSDUR_TX_RESP7E8,          /* FC sent on 0x7E8 */
        CanTpConf_CanTpTxFcNPdu_Resp7E8,
        CANTP_PHYSICAL,
        TRUE,                                /* CanTpRxPaddingActivation = CANTP_ON */
        CANTP_EX_BS,
        CANTP_EX_STMIN,
        CANTP_EX_WFTMAX,
        CANTP_MS_TO_TICKS(CANTP_EX_NAR_MS),
        CANTP_MS_TO_TICKS(CANTP_EX_NBR_MS),
        CANTP_MS_TO_TICKS(CANTP_EX_NCR_MS)
    },
    {   /* CanTpConf_CanTpRxNSdu_DiagFuncRx: functional requests on 0x7DF, SF only
         * [SWS_CanTp_00092]. No CanTpTxFcNPdu: FC fields are unused. */
        CanTpConf_CanTpRxNPdu_FuncReq7DF,
        CANTP_CFG_PDUR_DIAG_FUNC_RX,
        CANTP_CFG_LSDUR_TX_RESP7E8,
        CanTpConf_CanTpTxFcNPdu_Resp7E8,
        CANTP_FUNCTIONAL,
        TRUE,
        CANTP_EX_BS,
        CANTP_EX_STMIN,
        CANTP_EX_WFTMAX,
        CANTP_MS_TO_TICKS(CANTP_EX_NAR_MS),
        CANTP_MS_TO_TICKS(CANTP_EX_NBR_MS),
        CANTP_MS_TO_TICKS(CANTP_EX_NCR_MS)
    }
};

/* ---- CanTpTxNSdu: index = CanTpTxNSduId --------------------------------- */
const CanTp_TxNSduCfgType CanTp_TxNSduCfg[CANTP_CFG_NUM_TX_NSDU] =
{
    {   /* CanTpConf_CanTpTxNSdu_DiagTx: responses on 0x7E8, FC received on 0x7E0 */
        CANTP_CFG_LSDUR_TX_RESP7E8,
        CanTpConf_CanTpTxNPdu_Resp7E8,
        CanTpConf_CanTpRxFcNPdu_Req7E0,
        CANTP_CFG_PDUR_DIAG_TX,
        CANTP_PHYSICAL,
        TRUE,                                /* CanTpTxPaddingActivation = CANTP_ON */
        TRUE,                                /* CanTpTc */
        CANTP_MS_TO_TICKS(CANTP_EX_NAS_MS),
        CANTP_MS_TO_TICKS(CANTP_EX_NBS_MS),
        CANTP_MS_TO_TICKS(CANTP_EX_NCS_MS)
    }
};
